SELECT rr.*, r.visibility AS resource_visibility, r.owner_id AS resource_owner_id, COALESCE(r.title, rr.resource_title) AS resource_title FROM resource_report rr LEFT JOIN resource r ON rr.resource_id = r.id
WHERE rr.status = #{status}
ORDER BY rr.created_at DESC

SELECT rr.*, r.visibility AS resource_visibility, r.owner_id AS resource_owner_id, COALESCE(r.title, rr.resource_title) AS resource_title FROM resource_report rr LEFT JOIN resource r ON rr.resource_id = r.id WHERE rr.user_id = #{userId}
AND rr.status = #{status}
ORDER BY rr.created_at DESC

mapper.update:
UPDATE resource_report
status = #{status}, review_reply = #{reviewReply}, reviewed_at = #{reviewedAt}, reason = #{reason}, cancelled = #{cancelled}, updated_at = NOW()
WHERE id = #{id}
